		{ id = "fallen_dragon", icon = "INV_Jewelry_Necklace_12", names = { enUS = "Pendant of the Fallen Dragon", plPL = "Wisior Upadłego Smoka", deDE = "Anhänger des gefallenen Drachen", ptBR = "Pingente do Dragão Caído", esES = "Colgante del Dragón Caído", frFR = "Pendentif du dragon déchu", trTR = "Pendant of the Fallen Dragon", ruRU = "Подвеска павшего дракона", zhCN = "陨落巨龙垂饰", koKR = "몰락한 용의 펜던트" }, q = 4, desc = { enUS = "A killing blow leaves you at 50% health instead, once every 60 sec\nIncreases your maximum health by 20%.\nRestores 5 health per second.", plPL = "Śmiertelny cios zostawia cię zamiast tego z 50% zdrowia, raz na 60 s\nZwiększa twoje maksymalne zdrowie o 20%.\nPrzywraca 5 zdrowia na sekundę.", deDE = "Ein tödlicher Hieb lässt dich stattdessen mit 50% Gesundheit zurück, einmal alle 60 Sek.\nErhöht deine maximale Gesundheit um 20%.\nStellt 5 Gesundheit pro Sekunde wieder her.", ptBR = "Um golpe fatal deixa você com 50% de vida em vez disso, uma vez a cada 60 s\nAumenta sua vida máxima em 20%.\nRestaura 5 de vida por segundo.", esES = "Un golpe mortal te deja en cambio con 50% de salud, una vez cada 60 s\nAumenta tu salud máxima un 20%.\nRestaura 5 de salud por segundo.", frFR = "Un coup fatal vous laisse à 50% de vos points de vie à la place, une fois toutes les 60 s\nAugmente vos points de vie maximum de 20%.\nRend 5 points de vie par seconde.", trTR = "Öldürücü bir darbe seni bunun yerine 50% canla bırakır, 60 sn'de bir kez\nAzami canını 20% artırır.\nSaniyede 5 can yeniler.", ruRU = "Смертельный удар вместо этого оставляет вам 50% здоровья, раз в 60 сек.\nУвеличивает ваш макс. запас здоровья на 20%.\nВосполняет 5 ед. здоровья в секунду.", zhCN = "致命一击会改为让你保留50%生命值，每60秒一次\n你的最大生命值提高20%。\n每秒恢复5点生命值。", koKR = "치명적인 일격을 받으면 대신 생명력 50%(으)로 남습니다 (60초마다 1회)\n최대 생명력이 20% 증가합니다.\n초당 생명력을 5 회복합니다." } },
		{ id = "malice_stone", icon = "INV_Jewelry_Necklace_29Naxxramas", names = { enUS = "Malice Stone Pendant", plPL = "Wisior z Kamienia Złości", deDE = "Bosheitssteinanhänger", ptBR = "Pingente da Pedra da Malícia", esES = "Colgante de piedra de malicia", frFR = "Pendentif en pierre de malveillance", trTR = "Malice Stone Pendant", ruRU = "Подвеска из камня злобы", zhCN = "怨恨之石垂饰", koKR = "악의의 돌 펜던트" }, q = 4, desc = { enUS = "Gives your spells a 20% chance to cast twice.\nReduces the cooldown of your spells by 8%.", plPL = "Daje twoim zaklęciom 20% szansy na podwójne rzucenie.\nSkraca czas odnowienia twoich zaklęć o 8%.", deDE = "Gibt deinen Zaubern eine Chance von 20%, doppelt gewirkt zu werden.\nVerringert die Abklingzeit deiner Zauber um 8%.", ptBR = "Dá aos seus feitiços 20% de chance de serem lançados duas vezes.\nReduz a recarga dos seus feitiços em 8%.", esES = "Da a tus hechizos un 20% de probabilidad de lanzarse dos veces.\nReduce el tiempo de reutilización de tus hechizos un 8%.", frFR = "Donne à vos sorts 20% de chances de se lancer deux fois.\nRéduit le temps de recharge de vos sorts de 8%.", trTR = "Büyülerine 20% iki kez kullanılma şansı verir.\nBüyülerinin bekleme süresini 8% azaltır.", ruRU = "Даёт вашим заклинаниям 20% вероятность примениться дважды.\nСокращает время восстановления ваших заклинаний на 8%.", zhCN = "使你的法术有20%几率施放两次。\n你的法术冷却时间缩短8%。", koKR = "주문이 20% 확률로 두 번 시전됩니다.\n주문의 재사용 대기시간이 8% 감소합니다." } },
